using RvtIO.Internal;
using RvtIO.Model;
using RvtIO.Parsing;
using RvtIO.Ifc;
using Xunit;

namespace RvtIO.Tests;

public class PlanarSpaceEqualCountCoverageTests
{
    [Theory]
    [InlineData("flags")]
    [InlineData("owner")]
    [InlineData("first-edge")]
    [InlineData("last-edge")]
    [InlineData("open")]
    public void LostRegion_WithInvalidAuthoredLoop_CannotReturnPartialLegacyGeometry(string mutation)
    {
        byte[] block = Convert.FromBase64String(Fixture);
        // Schema-walked loop 113 at 11067: nextLoop=162, Face=7, first=33,
        // last=90, open=0. Its non-null nextLoop pointer occupies six bytes.
        void U32(int offset, uint value) => BitConverter.GetBytes(value).CopyTo(block, offset);
        switch (mutation)
        {
            case "flags": U32(11067 + 12, 0); break;
            case "owner": U32(11067 + 22, 8); break;
            case "first-edge": U32(11067 + 26, 999999); break;
            case "last-edge": U32(11067 + 30, 999999); break;
            case "open": block[11067 + 66] = 1; break;
        }
        Assert.Null(GRepParserV2.ParseExactPlanarSpaceBoundary(
            block, 0, BitConverter.ToUInt32(block, 8), 7481504));
    }

    [Fact]
    public void EqualFaceAndPolygonCounts_DoNotConfirmCompleteTrimCoverage()
    {
        byte[] block = Convert.FromBase64String(Fixture);
        var geometry = Assert.IsType<GRepData>(GRepParserV2.ParseExactPlanarSpaceBoundary(
            block, 0, BitConverter.ToUInt32(block, 8), 7481504));
        // 26 authored Face handles include one Face with two separate regions.
        // The previous count-only shortcut silently lost the second region.
        Assert.Equal(27, geometry.Faces.Count);
        var solid = Assert.Single(geometry.Solids);
        Assert.True(solid.IsClosed);
        Assert.Equal(Enumerable.Range(0, 27), solid.FaceIndices.Order());
        var model = Assert.IsType<GeometryData>(ElementBuilder.BuildGeometryData(geometry));
        Assert.True(IfcExporter.TryOrientExactFacetedShell(model.Faces,
            solid.FaceIndices, out var oriented, triangulateNonPlanarFaces: false));
        Assert.Equal(27, oriented.Count);
        Assert.Null(GRepParserV2.Parse(block, 0, BitConverter.ToUInt32(block, 8)));
        Assert.Equal(Convert.FromBase64String(Fixture), block);
    }

    // Complete source GElement cache of owner 7481504. Geometry only.
    private const string Fixture = "";
}
